import "fmt"
func main() {
    hosts := []string{"web1", "web2"}
    for i, h := range hosts { fmt.Println(i, h) }
}

var wg sync.WaitGroup
for _, h := range hosts {
    wg.Add(1)
    go func(h string) { defer wg.Done(); check(h) }(h)
}
wg.Wait()

results := make(chan string, len(hosts))
for _, h := range hosts { go func(h string) { results <- check(h) }(h) }
for range hosts { fmt.Println(<-results) }

